import sys

def main():
    lines = sys.stdin.read().strip().split()
    if len(lines) < 3:
        return

    P = float(lines[0])
    R = float(lines[1])
    T = float(lines[2])

    si = (P * R * T) / 100

    if si == int(si):
        print(int(si))
    else:
        print(si)

if __name__ == "__main__":
    main()
